mapper.sql:
WHERE R.deviceIdx = #{deviceIdx}



			AND DATE(R.currentDateTime) = CURDATE()


			AND DATE(R.currentDateTime) = DATE(#{workDate})

mapper.select:
SELECT
FROM TB_REPORT_HISTORY H INNER JOIN TB_REPORT R ON R.id = H.reportId LEFT JOIN TB_DEVICE D ON D.id = H.deviceIdx LEFT JOIN TB_PENETRATION_HISTORY PH ON PH.reportHistoryId = H.id LEFT JOIN TB_PIECE_HISTORY PI ON PI.reportHistoryId = H.id
ORDER BY H.modifiedAt DESC, H.id DESC LIMIT #{startRow}, #{pageSize}
